// Generated by Step 2
// Modified by T01: 按 GB/T 31917-2015 表 2 重排键位
// Modified by T02: 字符集收敛为 KyrgyzAlphabet 单一真源，布局与硬件映射共用 LAYER1 / LAYER2
package com.example.kyrgyzkeyboard.keyboard

/**
 * 布局类型：字母主布局 / 数字键盘布局 / 符号布局。
 */
enum class LayoutType { DEFAULT, DIGITAL, SYMBOL }

/**
 * 一行按键。
 */
data class KeyboardRow(val keys: List<KyrgyzKey>)

/**
 * 柯尔克孜文字符集**单一真源**。
 *
 * 依据：
 * - GB/T 31917-2015 附录 A 表 A.1 —— 30 个标准字母
 * - GB/T 31917-2015 表 2 —— 键位配置（[LAYER1] / [LAYER2]）
 * - GB/T 31917-2015 附录 C —— 7 个专用符号（[PUNCTUATION]）
 * - GB/T 32412-2015 —— 双向控制符（[BIDI_CONTROLS]）
 *
 * **本文件是全项目唯一允许出现 `\uXXXX` 转义的地方。**
 * 其余模块必须引用这里的常量或表；新增字符也只能加在这里。
 */
object KyrgyzAlphabet {

    /**
     * 字母元数据。
     *
     * @param code  单字符码位
     * @param name  拉丁转写名（便于检索、日志与测试失败信息）
     * @param vowel 是否元音（附录 A 中 8 个）
     * @param layer 表 2 中所属层：1 = 直档，2 = Shift 档
     */
    data class Letter(val code: String, val name: String, val vowel: Boolean, val layer: Int)

    // ============================================================
    // 30 个标准字母（GB/T 31917-2015 附录 A 表 A.1）
    // ============================================================

    const val ALEF = "\u0627"  // ا
    const val BE = "\u0628"    // ب
    const val PE = "\u067E"    // پ
    const val NUN = "\u0646"   // ن
    const val TE = "\u062A"    // ت
    const val JEEM = "\u062C"  // ج
    const val CHE = "\u0686"   // چ
    const val HAH = "\u062D"   // ح
    const val FEH = "\u0641"   // ف
    const val QAF = "\u0642"   // ق
    const val AIN = "\u0639"   // ع
    const val KAF = "\u0643"   // ك
    const val GAF = "\u06AF"   // گ
    const val NG = "\u06AD"    // ڭ
    const val LAM = "\u0644"   // ل
    const val MEEM = "\u0645"  // م
    const val WAU = "\u0648"   // و
    const val OE = "\u06C5"    // ۅ
    const val UU = "\u06C7"    // ۇ
    const val UE = "\u06C9"    // ۉ
    const val VE = "\u06CB"    // ۋ
    const val SEEN = "\u0633"  // س
    const val SHEEN = "\u0634" // ش
    const val DAL = "\u062F"   // د
    const val RE = "\u0631"    // ر
    const val ZAIN = "\u0632"  // ز
    const val E = "\u06D5"     // ە
    const val YI = "\u0649"    // ى
    const val HAMZA = "\u0626" // ئ
    const val YE = "\u064A"    // ي

    /** 30 个标准字母（顺序 = 表 A.1），每项带元数据。 */
    val ENTRIES: List<Letter> = listOf(
        Letter(ALEF, "alef", true, 1),
        Letter(BE, "be", false, 1),
        Letter(PE, "pe", false, 1),
        Letter(NUN, "nun", false, 1),
        Letter(TE, "te", false, 1),
        Letter(JEEM, "jeem", false, 1),
        Letter(CHE, "che", false, 1),
        Letter(HAH, "hah", false, 2),
        Letter(FEH, "feh", false, 2),
        Letter(QAF, "qaf", false, 1),
        Letter(AIN, "ain", false, 1),
        Letter(KAF, "kaf", false, 1),
        Letter(GAF, "gaf", false, 2),
        Letter(NG, "ng", false, 1),
        Letter(LAM, "lam", false, 1),
        Letter(MEEM, "meem", false, 1),
        Letter(WAU, "wau", false, 1),
        Letter(OE, "oe", true, 1),
        Letter(UU, "uu", true, 1),
        Letter(UE, "ue", true, 1),
        Letter(VE, "ve", false, 1),
        Letter(SEEN, "seen", false, 1),
        Letter(SHEEN, "sheen", false, 1),
        Letter(DAL, "dal", false, 1),
        Letter(RE, "re", false, 1),
        Letter(ZAIN, "zain", false, 1),
        Letter(E, "e", true, 1),
        Letter(YI, "yi", true, 1),
        Letter(HAMZA, "hamza", true, 1),
        Letter(YE, "ye", true, 1)
    )

    /** 30 个标准字母的码位（顺序同 [ENTRIES]）。 */
    val LETTERS: List<String> = ENTRIES.map { it.code }

    /** 8 个元音。 */
    val VOWELS: Set<String> = ENTRIES.filter { it.vowel }.map { it.code }.toSet()

    /** 22 个辅音 = 30 字母 − 元音。 */
    val CONSONANTS: Set<String> = LETTERS.toSet() - VOWELS

    // ============================================================
    // 表 2 额外字符
    // ============================================================

    /**
     * ھ —— **不属于** 30 字母（附录 A 无此码位），但表 2 为它分配了 C01 键位。
     */
    const val HEH_DOACHASHMEE = "\u06BE"

    /** 键盘上可输出的字母集合 = 30 字母 ∪ {ھ}。 */
    val KEYBOARD_LETTERS: Set<String> = LETTERS.toSet() + HEH_DOACHASHMEE

    /**
     * 30 字母之外的阿拉伯字母，仅用于双向文本判定（外来词/混排文本可能出现），
     * 不参与键盘输入，也不进入 [LETTERS]。
     */
    val EXTENSION_LETTERS: List<String> = listOf("خ", "ذ", "ژ", "ص", "ض", "ط", "ظ", "غ", "ء")

    /** 波斯 ي(U+06CC)，仅用于输入归一化（折叠到标准 [YE]）。 */
    const val FARSI_YEH = "\u06CC"

    // ============================================================
    // 附录 C 专用符号
    // ============================================================

    const val GUILLEMET_LEFT = "\u00AB"  // «
    const val GUILLEMET_RIGHT = "\u00BB" // »
    const val COMMA = "\u060C"           // ،
    const val SEMICOLON = "\u061B"       // ؛
    const val QUESTION = "\u061F"        // ؟
    const val TATWEEL = "\u0640"         // ـ
    const val ELLIPSIS = "\u2026"        // …
    const val PERIOD = "."               // 表 2 B09 的句点（ASCII）

    /** 7 个专用符号（附录 C 表 C.1）。 */
    val PUNCTUATION: List<String> = listOf(
        GUILLEMET_LEFT, GUILLEMET_RIGHT, COMMA, SEMICOLON, QUESTION, TATWEEL, ELLIPSIS
    )

    // ============================================================
    // 双向控制符（GB/T 32412-2015）
    // ============================================================

    const val RLM = "\u200F"
    const val LRM = "\u200E"
    const val RLE = "\u202B"
    const val LRE = "\u202A"
    const val PDF = "\u202C"

    val BIDI_CONTROLS: List<String> = listOf(RLM, LRM, RLE, LRE, PDF)

    // ============================================================
    // 附加符号
    // ============================================================

    const val FATHA = "\u064E"
    const val KASRA = "\u0650"
    const val DAMMA = "\u064F"
    const val SHADDA = "\u0651"

    val DIACRITICS: List<String> = listOf(FATHA, KASRA, DAMMA, SHADDA)

    // ============================================================
    // 键位表（GB/T 31917-2015 表 2）
    // ============================================================

    /**
     * 表 2 第 1 层：QWERTY 键 → 输出字符。
     *
     * 行对应：`A`…`'` ↔ C01–C11，`Q`…`P` ↔ D01–D10，`Z`…`/` ↔ B01–B10。
     * 表 2 的 E00（`ـ` / `…`）无对应物理键位——默认布局不渲染数字行，改由符号布局输入。
     */
    val LAYER1: Map<Char, String> = mapOf(
        // D 行 D01–D10
        'q' to CHE, 'w' to VE, 'e' to E, 'r' to RE, 't' to TE,
        'y' to YE, 'u' to UU, 'i' to NG, 'o' to WAU, 'p' to PE,
        // C 行 C01–C11
        'a' to HEH_DOACHASHMEE, 's' to SEEN, 'd' to DAL, 'f' to ALEF, 'g' to E,
        'h' to YI, 'j' to QAF, 'k' to KAF, 'l' to LAM,
        ';' to SEMICOLON, '\'' to GUILLEMET_RIGHT,
        // B 行 B01–B10
        'z' to ZAIN, 'x' to SHEEN, 'c' to AIN, 'v' to UE, 'b' to BE,
        'n' to NUN, 'm' to MEEM, ',' to COMMA, '.' to PERIOD, '/' to HAMZA
    )

    /**
     * 表 2 第 2 层（Shift）：只列标准明确规定的键。
     * 未列出的键由调用方回落到 [LAYER1]。
     */
    val LAYER2: Map<Char, String> = mapOf(
        'f' to FEH,             // C04
        'g' to GAF,             // C05
        'h' to HAH,             // C06
        '\'' to GUILLEMET_LEFT, // C11
        '/' to QUESTION         // B10
    )

    /**
     * 表 2 未规定键位、暂挂长按变体的字符。
     *
     * TODO(标准待补)：等标准补齐 `ج`(062C) / `ۅ`(06C5) 的键位后删除本表，
     * 并移除布局里的 `TODO(标准待补)` 注释。
     */
    val LONG_PRESS: Map<Char, String> = mapOf(
        'q' to JEEM, // 长按 چ → ج
        'w' to OE    // 长按 ۋ → ۅ
    )
}

object KyrgyzKeyboardLayouts {

    /** 表 2 的 C 行（C01–C11）对应的 QWERTY 键序列。 */
    private const val ROW_C = "asdfghjkl;'"

    /** 表 2 的 D 行（D01–D10）对应的 QWERTY 键序列。 */
    private const val ROW_D = "qwertyuiop"

    /** 表 2 的 B 行（B01–B10）对应的 QWERTY 键序列。 */
    private const val ROW_B = "zxcvbnm,./"

    /**
     * 按 QWERTY 键序列 + 层表生成一行键。
     * 层表中缺省的键回落到 [KyrgyzAlphabet.LAYER1]（表 2 未规定第 2 层的键沿用第 1 层）。
     */
    private fun rowOf(keys: String, layer: Map<Char, String>): List<KyrgyzKey> =
        keys.map { k ->
            val ch = layer[k] ?: KyrgyzAlphabet.LAYER1.getValue(k)
            val variants = KyrgyzAlphabet.LONG_PRESS[k]?.let { listOf(it) }.orEmpty()
            if (ch in KyrgyzAlphabet.KEYBOARD_LETTERS) KyrgyzKey.letter(ch, variants)
            else KyrgyzKey.symbol(ch)
        }

    /**
     * 字母主布局（第 1 层），逐键对齐 GB/T 31917-2015 表 2。
     *
     * 行内容由 [KyrgyzAlphabet.LAYER1] 生成，本对象不再重复维护字符。
     */
    val DefaultLayout: List<KeyboardRow> = listOf(
        // C 行（C01–C11）：ھ س د ا ە ى ق ك ل ؛ »
        KeyboardRow(listOf(KyrgyzKey.switchDigital("123")) + rowOf(ROW_C, KyrgyzAlphabet.LAYER1)),
        // D 行（D01–D10）：چ ۋ ە ر ت ي ۇ ڭ و پ
        KeyboardRow(rowOf(ROW_D, KyrgyzAlphabet.LAYER1)),
        // B 行（B01–B10）：ز ش ع ۉ ب ن م ، . ئ
        KeyboardRow(
            listOf(KyrgyzKey.shift()) +
                rowOf(ROW_B, KyrgyzAlphabet.LAYER1) +
                listOf(KyrgyzKey.backspace())
        ),
        // 功能键区（表 2 未覆盖）
        KeyboardRow(listOf(
            KyrgyzKey.switchLayout("符号"),
            KyrgyzKey.switchLanguage("قىر"),
            KyrgyzKey.space(),
            KyrgyzKey.symbol("!"),
            KyrgyzKey.newline()
        ))
    )

    /**
     * Shift 层（第 2 层）：按表 2 已公布的第 2 层键位填充
     * （C04 ف、C05 گ、C06 ح、C11 «、B10 ؟）；其余键沿用第 1 层。
     */
    val ShiftLayout: List<KeyboardRow> = listOf(
        // C 行：ھ س د ف گ ح ق ك ل ؛ «
        KeyboardRow(listOf(KyrgyzKey.switchDigital("123")) + rowOf(ROW_C, KyrgyzAlphabet.LAYER2)),
        // D 行：表 2 未规定第 2 层，全部沿用第 1 层
        KeyboardRow(rowOf(ROW_D, KyrgyzAlphabet.LAYER2)),
        // B 行：ز ش ع ۉ ب ن م ، . ؟
        KeyboardRow(
            listOf(KyrgyzKey.shift()) +
                rowOf(ROW_B, KyrgyzAlphabet.LAYER2) +
                listOf(KyrgyzKey.backspace())
        ),
        // 功能键区（表 2 未覆盖）
        KeyboardRow(listOf(
            KyrgyzKey.switchLayout("符号"),
            KyrgyzKey.switchLanguage("قىر"),
            KyrgyzKey.space(),
            KyrgyzKey.symbol("?"),
            KyrgyzKey.newline()
        ))
    )

    /**
     * 【已存档】原九宫格连按循环布局：连按同一键在数字与柯语字母之间循环。
     * 因体验问题暂时下线，保留完整代码以便后续完善后重新启用。
     * 当前未接入任何切换路径（forType 不再返回本布局）。
     */
    val ArchivedKyrgyzNineGridLayout: List<KeyboardRow> = listOf(
        // ==================== 顶部快捷功能栏 ====================
        KeyboardRow(listOf(
            KyrgyzKey.switchLayout("字母"), // 切换回字母键盘
            KyrgyzKey.switchLanguage("🌐"), // 语言切换
            KyrgyzKey.symbol(KyrgyzAlphabet.QUESTION),
            KyrgyzKey.symbol(KyrgyzAlphabet.COMMA),
            KyrgyzKey.symbol(KyrgyzAlphabet.PERIOD),
            KyrgyzKey.symbol("!"),
            KyrgyzKey.backspace()          // 退格（快捷版）
        )),
        // Row 1 (1, 2, 3)
        KeyboardRow(listOf(
            KyrgyzKey.digitalKey(
                label = "1",
                symbols = listOf(
                    KyrgyzAlphabet.PERIOD, KyrgyzAlphabet.COMMA, KyrgyzAlphabet.SEMICOLON,
                    KyrgyzAlphabet.QUESTION, "!"
                )
            ),
            KyrgyzKey.digitalKey(
                label = "2",
                symbols = listOf(KyrgyzAlphabet.ALEF, KyrgyzAlphabet.BE, KyrgyzAlphabet.CHE, KyrgyzAlphabet.AIN)
            ),
            KyrgyzKey.digitalKey(
                label = "3",
                symbols = listOf(KyrgyzAlphabet.DAL, KyrgyzAlphabet.E, KyrgyzAlphabet.HAMZA, KyrgyzAlphabet.FEH)
            )
        )),
        // Row 2 (4, 5, 6)
        KeyboardRow(listOf(
            KyrgyzKey.digitalKey(
                label = "4",
                symbols = listOf(KyrgyzAlphabet.GAF, KyrgyzAlphabet.HAH, KyrgyzAlphabet.YI)
            ),
            KyrgyzKey.digitalKey(
                label = "5",
                symbols = listOf(KyrgyzAlphabet.JEEM, KyrgyzAlphabet.KAF, KyrgyzAlphabet.LAM)
            ),
            KyrgyzKey.digitalKey(
                label = "6",
                symbols = listOf(KyrgyzAlphabet.MEEM, KyrgyzAlphabet.NUN, KyrgyzAlphabet.WAU, KyrgyzAlphabet.NG)
            )
        )),
        // Row 3 (7, 8, 9)
        KeyboardRow(listOf(
            KyrgyzKey.digitalKey(
                label = "7",
                symbols = listOf(KyrgyzAlphabet.PE, KyrgyzAlphabet.QAF, KyrgyzAlphabet.RE, KyrgyzAlphabet.SEEN)
            ),
            KyrgyzKey.digitalKey(
                label = "8",
                symbols = listOf(KyrgyzAlphabet.TE, KyrgyzAlphabet.UU, KyrgyzAlphabet.OE, KyrgyzAlphabet.UE)
            ),
            KyrgyzKey.digitalKey(
                label = "9",
                symbols = listOf(KyrgyzAlphabet.VE, KyrgyzAlphabet.SHEEN, KyrgyzAlphabet.YE, KyrgyzAlphabet.ZAIN)
            )
        )),
        // Row 4 (双向控制符 + 0 + 双向控制符)
        KeyboardRow(listOf(
            KyrgyzKey.symbol(KyrgyzAlphabet.RLM),
            KyrgyzKey.digitalKey(
                label = "0",
                symbols = listOf(
                    " ", KyrgyzAlphabet.TATWEEL, KyrgyzAlphabet.ELLIPSIS,
                    KyrgyzAlphabet.GUILLEMET_LEFT, KyrgyzAlphabet.GUILLEMET_RIGHT
                )
            ),
            KyrgyzKey.symbol(KyrgyzAlphabet.LRM)
        )),
        // Row 5 (底部功能键)
        KeyboardRow(listOf(
            KyrgyzKey.switchLayout("符号"),
            KyrgyzKey.space(),
            KyrgyzKey.newline()
        ))
    )

    /**
     * 纯数字九键布局：仅输出阿拉伯数字与小数点，无连按循环、无柯语字母联想。
     * 供用户在需要输入数字时快速选择。
     */
    val DigitalLayout: List<KeyboardRow> = listOf(
        // Row 1 (1, 2, 3)
        KeyboardRow(listOf(
            KyrgyzKey.digitalKey(label = "1", symbols = emptyList()),
            KyrgyzKey.digitalKey(label = "2", symbols = emptyList()),
            KyrgyzKey.digitalKey(label = "3", symbols = emptyList())
        )),
        // Row 2 (4, 5, 6)
        KeyboardRow(listOf(
            KyrgyzKey.digitalKey(label = "4", symbols = emptyList()),
            KyrgyzKey.digitalKey(label = "5", symbols = emptyList()),
            KyrgyzKey.digitalKey(label = "6", symbols = emptyList())
        )),
        // Row 3 (7, 8, 9)
        KeyboardRow(listOf(
            KyrgyzKey.digitalKey(label = "7", symbols = emptyList()),
            KyrgyzKey.digitalKey(label = "8", symbols = emptyList()),
            KyrgyzKey.digitalKey(label = "9", symbols = emptyList())
        )),
        // Row 4 (小数点, 0, 退格)
        KeyboardRow(listOf(
            KyrgyzKey.digitalKey(label = ".", symbols = emptyList()),
            KyrgyzKey.digitalKey(label = "0", symbols = emptyList()),
            KyrgyzKey.backspace()
        )),
        // Row 5 (功能键：字母 / 符号 / 空格 / 换行)
        KeyboardRow(listOf(
            KyrgyzKey.switchDigital("字母"),
            KyrgyzKey.switchLayout("符号"),
            KyrgyzKey.space(),
            KyrgyzKey.newline()
        ))
    )

    /**
     * 符号 / 数字布局。
     * 增加快捷字母键盘切换按钮。
     */
    val SymbolLayout: List<KeyboardRow> = listOf(
        KeyboardRow(listOf(
            KyrgyzKey.switchDigital("字母"), // 快捷切回字母
            KyrgyzKey.symbol("1"), KyrgyzKey.symbol("2"), KyrgyzKey.symbol("3"), KyrgyzKey.symbol("4"),
            KyrgyzKey.symbol("5"), KyrgyzKey.symbol("6"), KyrgyzKey.symbol("7"), KyrgyzKey.symbol("8"),
            KyrgyzKey.symbol("9"), KyrgyzKey.symbol("0")
        )),
        KeyboardRow(listOf(
            KyrgyzKey.symbol("@"), KyrgyzKey.symbol("#"), KyrgyzKey.symbol("\$"),
            KyrgyzKey.symbol("%"), KyrgyzKey.symbol("&"), KyrgyzKey.symbol("*"),
            KyrgyzKey.symbol("-"), KyrgyzKey.symbol("+"), KyrgyzKey.symbol("("),
            KyrgyzKey.symbol(")")
        )),
        KeyboardRow(listOf(
            KyrgyzKey.symbol("!"), KyrgyzKey.symbol("\""), KyrgyzKey.symbol("'"),
            KyrgyzKey.symbol(":"), KyrgyzKey.symbol(";"), KyrgyzKey.symbol("/"),
            KyrgyzKey.symbol("?"), KyrgyzKey.symbol(KyrgyzAlphabet.COMMA),
            KyrgyzKey.symbol(KyrgyzAlphabet.SEMICOLON),
            KyrgyzKey.backspace()
        )),
        KeyboardRow(listOf(
            KyrgyzKey.switchLayout("ابج"),
            KyrgyzKey.symbol(KyrgyzAlphabet.GUILLEMET_LEFT),
            KyrgyzKey.symbol(KyrgyzAlphabet.GUILLEMET_RIGHT),
            KyrgyzKey.symbol(KyrgyzAlphabet.QUESTION),
            KyrgyzKey.symbol(KyrgyzAlphabet.TATWEEL),
            KyrgyzKey.symbol(KyrgyzAlphabet.ELLIPSIS),
            KyrgyzKey.symbol(KyrgyzAlphabet.RLM),
            KyrgyzKey.symbol(KyrgyzAlphabet.LRM),
            KyrgyzKey.space(),
            KyrgyzKey.newline()
        ))
    )

    /** 根据布局类型 + Shift 状态返回对应键盘行集合。 */
    fun forType(type: LayoutType, isShift: Boolean = false): List<KeyboardRow> = when (type) {
        LayoutType.DEFAULT -> if (isShift) ShiftLayout else DefaultLayout
        LayoutType.DIGITAL -> DigitalLayout
        LayoutType.SYMBOL -> SymbolLayout
    }
}
